// FoundationStereo's cost-volume construction (`build_gwc_volume`, `proj_cmb`,
// `build_concat_volume` and their concatenation), against PyTorch. Fixtures
// generated by tests/fixtures/cost_volume/generate.py and gen_real.py.
//
// Runs on whichever backend teeny-runtime was built for: CUDA, or RISC-V under qemu
// (`--no-default-features --features qemu`, with
// `TEENYC_QEMU_RISCV64=/usr/bin/qemu-riscv64-static` if only the static qemu exists).

#![cfg(any(feature = "cuda", feature = "qemu"))]

mod common;

use common::stereo_block::check_block;
use serial_test::serial;
use vision_rs::models::stereo::cost_volume::{CostVolumeDims, comb_volume, gwc_volume};

/// 16 channels in 4 groups, `proj_cmb` to 3, 11 disparities over 9 columns (so the
/// widest shifts are all zero), on 4x9 maps.
#[test]
#[serial]
fn comb_volume_matches_pytorch() -> anyhow::Result<()> {
    let dims = CostVolumeDims {
        feat: 16,
        groups: 4,
        proj: 3,
        disps: 11,
    };
    let f: &[usize] = &[1, 16, 4, 9];
    check_block(
        "cost_volume/small",
        "cost_volume/small",
        &[("fl", f), ("fr", f)],
        |i| {
            vec![
                ("gwc", gwc_volume::<f32>(&i[0], &i[1], 4, 11)),
                ("comb", comb_volume::<f32>(&dims, &i[0], &i[1])),
            ]
        },
        1e-5,
    )?;
    Ok(())
}

/// The volume with a real FoundationStereo checkpoint's `proj_cmb`, on the real 1/4
/// features (224 channels, 56x80) of the sample stereo pair at 224x320: 8 groups,
/// 104 disparities. Build the fixtures with tests/fixtures/cost_volume/gen_real.py,
/// point `FS_REAL_FIXTURES` at the directory holding `cost_volume_real/` and run with
/// `--ignored`.
#[test]
#[serial]
#[ignore = "needs FS_REAL_FIXTURES (real-checkpoint fixtures, not committed)"]
fn comb_volume_matches_real_checkpoint() -> anyhow::Result<()> {
    let root = std::env::var("FS_REAL_FIXTURES")
        .expect("set FS_REAL_FIXTURES to the real-checkpoint fixture directory");
    let dir = format!("{root}/cost_volume_real");
    let f: &[usize] = &[1, 224, 56, 80];
    check_block(
        "cost_volume_real",
        &dir,
        &[("fl", f), ("fr", f)],
        |i| {
            vec![(
                "comb",
                comb_volume::<f32>(&CostVolumeDims::foundation_stereo(), &i[0], &i[1]),
            )]
        },
        1e-5,
    )?;
    Ok(())
}
